var IMAGES = {
  img1: { mime: 'image/png', data: '' },
  img2: { mime: 'image/png', data: '' },
  img3: { mime: 'image/png', data: '' },
  img4: { mime: 'image/png', data: '' },
  img5: { mime: 'image/jpeg', data: '' },
  img6: { mime: 'image/png', data: '' },
  img7: { mime: 'image/png', data: '' },
  img8: { mime: 'image/png', data: '' },
  img9: { mime: 'image/png', data: '' },
  img10: { mime: 'image/png', data: '' },
  img11: { mime: 'image/png', data: '' },
  img12: { mime: 'image/png', data: '' },
  img13: { mime: 'image/png', data: '' },
  img14: { mime: 'image/png', data: '' },
};

function getAllImages() {
  var result = {};
  for (var key in IMAGES) {
    result[key] = 'data:' + IMAGES[key].mime + ';base64,' + IMAGES[key].data;
  }
  return result;
}

// 헤더의 작은 로고(img1·img2)만 먼저 돌려주는 함수. getAllImages()는 스크린샷·증빙 이미지까지
// 전부(14개, 수 MB) 한 번에 직렬화해서 보내느라 느려서, 항상 눈에 보이는 헤더 로고까지
// 그 전체 응답을 기다리게 되는 문제가 있었다. 로고만 먼저 받아 바로 채우고,
// 나머지 이미지는 이어서 getAllImages()로 받는다.
function getHeaderLogos() {
  var result = {};
  ['img1', 'img2'].forEach(function(key) {
    if (IMAGES[key]) result[key] = 'data:' + IMAGES[key].mime + ';base64,' + IMAGES[key].data;
  });
  return result;
}
